import{_ as o,o as t,c as i,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-28（材料 / 声学超材料 / 微结构玻璃）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-28-materials.md","filePath":"topics/materials/science-daily-2026-10-28-materials.md"}'),a={name:"topics/materials/science-daily-2026-10-28-materials.md"};function r(c,e,n,l,d,g){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="科学日报-·-2026-10-28-材料-声学超材料-微结构玻璃" tabindex="-1">科学日报 · 2026-10-28（材料 / 声学超材料 / 微结构玻璃） <a class="header-anchor" href="#科学日报-·-2026-10-28-材料-声学超材料-微结构玻璃" aria-label="Permalink to &quot;科学日报 · 2026-10-28（材料 / 声学超材料 / 微结构玻璃）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-激光雕刻玻璃做出-mhz-超声超材料——损耗比-3d-打印低-100-倍" tabindex="-1">科学日报 2026-10-28：激光雕刻玻璃做出 MHz 超声超材料——损耗比 3D 打印低 100 倍 <a class="header-anchor" href="#科学日报-2026-10-28-激光雕刻玻璃做出-mhz-超声超材料——损耗比-3d-打印低-100-倍" aria-label="Permalink to &quot;科学日报 2026-10-28：激光雕刻玻璃做出 MHz 超声超材料——损耗比 3D 打印低 100 倍&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ DOI: 10.1126/sciadv.aef0666 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：声学超材料能重塑声场，服务<strong>生物医学成像、临床治疗、无损检测</strong>；但在 <strong>MHz 频段</strong>可选<strong>架构极少</strong>，现有方案往往<strong>高衰减、难加工、调控能力有限</strong>。</li><li>本工作：用<strong>激光雕刻玻璃</strong>做 MHz 超声超材料。通过给「metavoxel」刻上不同图案，定义出一种<strong>各向异性</strong>超材料。</li><li>结果： <ul><li>相对未结构化玻璃，<strong>局域声速变化可达 20%</strong>；</li><li><strong>损耗比同类 3D 打印超材料低 100 倍</strong>；</li><li>据此定义一套<strong>可模块化组合</strong>的标准元件库，塑造<strong>复杂图案化超声场</strong>；</li><li>配套理论模型揭示了超材料行为的<strong>微结构起源</strong>，为「按需设计超声场」打开空间。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）： <ol><li><strong>「加工方式」决定 MHz 声学超材料能否落地</strong> —— MHz 需要亚毫米级结构，3D 打印在 <strong>MHz 频段</strong>因表面粗糙/材料内耗而<strong>高衰减</strong>；激光雕刻玻璃用「透明低内耗基材 + 微结构调制」把损耗降 100 倍。判据：<strong>当一个器件卡在「高损耗/难加工」而非「原理不通」时，先修加工路径（基材 + patterning 方式），而不是修设计。</strong> 这与 10-27 材料（MOF 次级配位球「改第二层环境」）、今日物理（换材料平台）同族——<strong>改路径优于加力度</strong>。</li><li><strong>「metavoxel + 模块化元件库」＝把材料做成可编程装配件</strong> —— 用有限几种刻图元胞拼出任意声场，是把「材料设计」变成「乐高式组合」。可迁移判据：<strong>当要覆盖无限多种目标响应时，先建一个「有限、可组合的标准元件库」，而不是为每个目标单独设计一种材料。</strong> 这与本库 <code>physics</code> 模块六「多传感器 + 计算重建」的拼装逻辑同构。</li><li><strong>跨域</strong>：MHz 超声成像与 10-26 神经科学（HD 吸引子/脑成像工具）在「工具决定能看见什么」上合流——<strong>测量工具的加工极限，就是观察能力的极限</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第47期 科学板块</p></blockquote><p>关键词：科学日报第47期、MHz 超声超材料、ultrasonic metamaterial、激光雕刻玻璃、laser-engraved glass、metavoxel、各向异性、局域声速变化 20%、损耗比 3D 打印低 100 倍、复杂图案化超声场、模块化元件库、生物医学成像、无损检测、加工路径决定落地、低内耗基材、按需设计超声场</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/physics/index.md</code>、<code>topics/materials/science-daily-2026-10-27-materials.md</code>（MOF 次级配位球）、<code>topics/biomedicine/index.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const u=o(a,[["render",r]]);export{p as __pageData,u as default};
